# ─────────────────────────────────────────────────────────────
#  Жардамчы функциялар
# ─────────────────────────────────────────────────────────────

def get_districts(oblast):
    """Облустагы райондордун/шаарлардын тизмеси."""
    node = GEO.get(oblast)
    if not node:
        return []
    if isinstance(node, dict):
        return list(node.keys())
    return list(node)


def get_localities(oblast, district):
    """Райондогу айыл аймактардын (же кичи райондордун) тизмеси."""
    node = GEO.get(oblast)
    if not isinstance(node, dict):
        return []
    sub = node.get(district)
    if isinstance(sub, dict):
        return list(sub.keys())
    if isinstance(sub, list):
        return list(sub)
    return []


def get_villages(oblast, district, locality):
    """Айыл аймактагы айылдардын тизмеси."""
    node = GEO.get(oblast)
    if not isinstance(node, dict):
        return []
    sub = node.get(district)
    if not isinstance(sub, dict):
        return []
    v = sub.get(locality)
    return list(v) if isinstance(v, list) else []


def L(text, lang="ky"):
    """Эки тилдүү сапты бөлүү: "Кыргызча / Русский" -> тандалган тил."""
    if not text or " / " not in text:
        return text or ""
    ky, ru = text.split(" / ", 1)
    return ru if lang == "ru" else ky


def ru_name(name):
    """Аймактын орусча аталышы."""
    return REGION_RU.get(name, name)


def get_categories(ad_type):
    """Жарыя түрү боюнча категориялар тизмеси."""
    return {
        "trade": TRADE_CATEGORIES,
        "rental": RENTAL_CATEGORIES,
        "delivery": DELIVERY_CATEGORIES,
        "service": SERVICE_CATEGORIES,
        "job": JOB_CATEGORIES,
        "wholesale": WHOLESALE_CATEGORIES,
        "cargo": CARGO_CATEGORIES,
        "jobseek": JOBSEEK_CATEGORIES,
    }.get(ad_type, JOB_CATEGORIES)


def get_category_by_id(ad_type, cat_id):
    for c in get_categories(ad_type):
        if c.get("id") == cat_id:
            return c
    return None


def get_subs_for_category(ad_type, cat_id):
    c = get_category_by_id(ad_type, cat_id)
    if c and c.get("subs"):
        return c["subs"]
    return ["Башка / Другое"]


def get_clothing_subs(demographic, season):
    base = CLOTHING_BASE.get(demographic) or CLOTHING_BASE["men"]
    extra = (CLOTHING_EXTRA.get(demographic) or CLOTHING_EXTRA["men"]) if season != "summer" else []
    return list(base) + list(extra) + ["Башка / Другое"]


def get_footwear_subs():
    return list(FOOTWEAR_BASE) + ["Башка / Другое"]


